@Test
public void testUpdateMany() throws IOException, ChecksumValidationException {
    Checksum checksumSha1 = new Checksum(ChecksumAlgorithm.SHA1);
    Checksum checksumMd5 = new Checksum(ChecksumAlgorithm.MD5);
    List<Checksum> checksums = new ArrayList<>();
    checksums.add(checksumSha1);
    checksums.add(checksumMd5);
    Path checkFile = getTestOutputDir().resolve("test-file1.txt");
    FileUtils.writeStringToFile(checkFile, FILE_ENCODING, "You know, I'm sick of following my dreams, man. " + "I'm just going to ask where they're going and hook up with 'em later. - Mitch Hedberg");
    ChecksumUtil.update(checksums, checkFile);
    assertEquals("Checksum SHA1", "e396119ae0542e85a74759602fd2f81e5d36d762", checksumSha1.getChecksum());
    assertEquals("Checksum MD5", "21c2c5ca87ec018adacb2e2fb3432219", checksumMd5.getChecksum());
}

@Test
public void testUpdateWholeUpdatePartial() {
    Checksum checksum = new Checksum(ChecksumAlgorithm.SHA1);
    assertEquals("Checksum unset", UNSET_SHA1, checksum.getChecksum());
    String expected = "066c2cbbc8cdaecb8ff97dcb84502462d6f575f3";
    byte[] reesepieces = "eatagramovabits".getBytes();
    checksum.update(reesepieces, 0, reesepieces.length);
    String actual = checksum.getChecksum();
    assertEquals("Expected", expected, actual);
    // Reset the checksum.
    checksum.reset();
    assertEquals("Checksum unset", UNSET_SHA1, checksum.getChecksum());
    // Now parse it again in 3 pieces.
    checksum.update(reesepieces, 0, 5);
    checksum.update(reesepieces, 5, 5);
    checksum.update(reesepieces, 10, reesepieces.length - 10);
    assertEquals("Expected", expected, actual);
}

@Test
public void testDeleteQuietly() throws IOException {
    Path tf = Files.createTempFile("FileUtilsTest", ".txt");
    assertTrue(Files.exists(tf));
    FileUtils.deleteQuietly(tf);
    assertFalse(Files.exists(tf));
    Path td = Files.createTempDirectory("FileUtilsTest");
    Path f1 = td.resolve("file1.txt");
    Path f2 = td.resolve("file2.txt");
    Path d1 = td.resolve("dir1");
    Files.createDirectory(d1);
    Path d11 = d1.resolve("dir11");
    Files.createDirectory(d11);
    Path f111 = d11.resolve("file111.txt");
    Path f112 = d11.resolve("file112.txt");
    Files.write(f1, "file1".getBytes());
    Files.write(f2, "file2".getBytes());
    Files.write(f111, "file111".getBytes());
    Files.write(f112, "file112".getBytes());
    assertTrue(Files.exists(d1));
    assertTrue(Files.exists(f1));
    assertTrue(Files.exists(f2));
    assertTrue(Files.exists(f111));
    assertTrue(Files.exists(f112));
    FileUtils.deleteQuietly(td);
    assertFalse(Files.exists(f1));
    assertFalse(Files.exists(f2));
    assertFalse(Files.exists(f111));
    assertFalse(Files.exists(f112));
    assertFalse(Files.exists(d1));
}

