@Test
public void testDefaultUserConfigFilename() throws Exception {
    DefaultArchivaConfiguration archivaConfiguration = (DefaultArchivaConfiguration) lookup(ArchivaConfiguration.class, "default");
    String expectedFile = System.getProperty("user.home") + "/.m2/archiva.xml";
    String systemFile = System.getProperty(ArchivaConfiguration.USER_CONFIG_PROPERTY);
    if (StringUtils.isNotEmpty(systemFile)) {
        expectedFile = systemFile;
    } else {
        String envFile = System.getenv(ArchivaConfiguration.USER_CONFIG_ENVVAR);
        if (StringUtils.isNotEmpty(envFile))
            expectedFile = envFile;
    }
    archivaConfiguration.reload();
    assertEquals(expectedFile, archivaConfiguration.getUserConfigFilename());
    assertEquals(System.getProperty("appserver.base", "${appserver.base}") + "/conf/archiva.xml", archivaConfiguration.getAltConfigFilename());
}

