    assertNotNull(repo);
    assertEquals("toto", repo.getName());
    timeout = 20000;
    while (timeout > 0 && repositoriesService.alreadyScanning(repo.getId())) {
        Thread.sleep(500);
        timeout -= 500;
    }
    service.deleteManagedRepository(repo.getId(), true);
    assertNull(service.getManagedRepository(repo.getId()));
}

