@SuppressWarnings("unchecked")
@Test
public void testProcess() throws Exception {
    List<ArtifactMetadata> newArtifacts = new ArrayList<>();
    ZonedDateTime whenGathered = ZonedDateTime.of(LocalDateTime.now(), ZoneId.systemDefault());
    newArtifacts.add(createArtifact("artifact-one", "1.0", whenGathered));
    newArtifacts.add(createArtifact("artifact-one", "1.1", whenGathered));
    newArtifacts.add(createArtifact("artifact-one", "2.0", whenGathered));
    newArtifacts.add(createArtifact("artifact-two", "1.0.1", whenGathered));
    newArtifacts.add(createArtifact("artifact-two", "1.0.2", whenGathered));
    newArtifacts.add(createArtifact("artifact-two", "1.0.3-SNAPSHOT", whenGathered));
    newArtifacts.add(createArtifact("artifact-three", "2.0-SNAPSHOT", whenGathered));
    newArtifacts.add(createArtifact("artifact-four", "1.1-beta-2", whenGathered));
    metadataRepository.setArtifactsByDateRange(newArtifacts);
    Map<String, String> reqParams = new HashMap<>();
    reqParams.put(RssFeedProcessor.KEY_REPO_ID, TEST_REPO);
    SyndFeed feed = newArtifactsProcessor.process(reqParams);
    // check that the date used in the call is close to the one passed (5 seconds difference at most)
    ZonedDateTime cal = ZonedDateTime.of(LocalDateTime.now(), ZoneId.systemDefault()).minusDays(30);
    assertTrue(ChronoUnit.SECONDS.between(cal.toInstant(), metadataRepository.getFrom().toInstant()) < 5);
    assertEquals(null, metadataRepository.getTo());
    assertEquals(TEST_REPO, metadataRepository.getRepoId());
    assertTrue(feed.getTitle().equals("New Artifacts in Repository 'test-repo'"));
    assertTrue(feed.getDescription().equals("New artifacts found in repository 'test-repo' during repository scan."));
    assertTrue(feed.getLanguage().equals("en-us"));
    assertTrue(feed.getPublishedDate().toInstant().truncatedTo(ChronoUnit.MILLIS).equals(whenGathered.toInstant().truncatedTo(ChronoUnit.MILLIS)));
    List<SyndEntry> entries = feed.getEntries();
    assertEquals(entries.size(), 1);
    assertTrue(entries.get(0).getTitle().contains("New Artifacts in Repository 'test-repo' as of "));
    assertTrue(entries.get(0).getPublishedDate().toInstant().truncatedTo(ChronoUnit.MILLIS).equals(whenGathered.toInstant().truncatedTo(ChronoUnit.MILLIS)));
}

@SuppressWarnings("unchecked")
@Test
public void testProcess() throws Exception {
    Date whenGatheredDate = new Date(123456789);
    ZonedDateTime whenGathered = ZonedDateTime.ofInstant(whenGatheredDate.toInstant(), ZoneId.systemDefault());
    ArtifactMetadata artifact1 = createArtifact(whenGathered, "1.0.1");
    ArtifactMetadata artifact2 = createArtifact(whenGathered, "1.0.2");
    Date whenGatheredNextDate = new Date(345678912);
    ZonedDateTime whenGatheredNext = ZonedDateTime.ofInstant(whenGatheredNextDate.toInstant(), ZoneId.systemDefault());
    ArtifactMetadata artifact3 = createArtifact(whenGatheredNext, "1.0.3-SNAPSHOT");
    Map<String, String> reqParams = new HashMap<>();
    reqParams.put(RssFeedProcessor.KEY_GROUP_ID, GROUP_ID);
    reqParams.put(RssFeedProcessor.KEY_ARTIFACT_ID, ARTIFACT_ID);
    expect(metadataRepository.getProjectVersions(session, TEST_REPO, GROUP_ID, ARTIFACT_ID)).andReturn(Arrays.asList("1.0.1", "1.0.2", "1.0.3-SNAPSHOT"));
    expect(metadataRepository.getArtifacts(session, TEST_REPO, GROUP_ID, ARTIFACT_ID, "1.0.1")).andReturn(Collections.singletonList(artifact1));
    expect(metadataRepository.getArtifacts(session, TEST_REPO, GROUP_ID, ARTIFACT_ID, "1.0.2")).andReturn(Collections.singletonList(artifact2));
    expect(metadataRepository.getArtifacts(session, TEST_REPO, GROUP_ID, ARTIFACT_ID, "1.0.3-SNAPSHOT")).andReturn(Collections.singletonList(artifact3));
    metadataRepositoryControl.replay();
    SyndFeed feed = newVersionsProcessor.process(reqParams);
    assertEquals("New Versions of Artifact 'org.apache.archiva:artifact-two'", feed.getTitle());
    assertEquals("New versions of artifact 'org.apache.archiva:artifact-two' found during repository scan.", feed.getDescription());
    assertEquals("en-us", feed.getLanguage());
    assertEquals(whenGatheredNext.toInstant(), ZonedDateTime.ofInstant(feed.getPublishedDate().toInstant(), ZoneId.systemDefault()).toInstant());
    List<SyndEntry> entries = feed.getEntries();
    assertEquals(2, entries.size());
    assertTrue(entries.get(0).getTitle().contains("New Versions of Artifact 'org.apache.archiva:artifact-two' as of "));
    assertEquals(whenGathered.toInstant(), entries.get(0).getPublishedDate().toInstant());
    assertTrue(entries.get(1).getTitle().contains("New Versions of Artifact 'org.apache.archiva:artifact-two' as of "));
    assertEquals(whenGatheredNext.toInstant(), entries.get(1).getPublishedDate().toInstant());
    metadataRepositoryControl.verify();
}

@SuppressWarnings("unchecked")
@Test
public void testNewFeed() throws Exception {
    List<RssFeedEntry> entries = new ArrayList<>();
    RssFeedEntry entry = new RssFeedEntry("Item 1");
    Date whenGathered = new Date(System.currentTimeMillis());
    entry.setDescription("RSS 2.0 feed item 1.");
    entry.setPublishedDate(whenGathered);
    entries.add(entry);
    entry = new RssFeedEntry("Item 2");
    entry.setDescription("RSS 2.0 feed item 2.");
    entry.setPublishedDate(whenGathered);
    entries.add(entry);
    entry = new RssFeedEntry("Item 3");
    entry.setDescription("RSS 2.0 feed item 3.");
    entry.setPublishedDate(whenGathered);
    entries.add(entry);
    SyndFeed feed = generator.generateFeed("Test Feed", "The test feed from Archiva.", entries);
    assertEquals("Test Feed", feed.getTitle());
    assertEquals("The test feed from Archiva.", feed.getDescription());
    assertEquals("en-us", feed.getLanguage());
    assertEquals(entries.get(2).getPublishedDate(), feed.getPublishedDate());
    List<SyndEntry> syndEntries = feed.getEntries();
    assertEquals(3, syndEntries.size());
    assertEquals("Item 1", syndEntries.get(0).getTitle());
    assertEquals("Item 2", syndEntries.get(1).getTitle());
    assertEquals("Item 3", syndEntries.get(2).getTitle());
}

