    factoryControl.replay();
    EasyMock.expect(metadataRepository.getMetadataFacets(session, TEST_REPO_ID, AuditEvent.FACET_ID)).andReturn(eventNames.get(TEST_REPO_ID));
    EasyMock.expect(metadataRepository.getMetadataFacets(session, TEST_REPO_ID_2, AuditEvent.FACET_ID)).andReturn(eventNames.get(TEST_REPO_ID_2));
    for (AuditEvent event : events.subList(1, events.size())) {
        EasyMock.expect(metadataRepository.getMetadataFacet(session, event.getRepositoryId(), AuditEvent.FACET_ID, event.getName())).andReturn(event);
    }
