    metadataRepository.addMetadataFacet(session, TEST_REPO_ID, stats2);
    expect(metadataRepository.getMetadataFacets(session, TEST_REPO_ID, DefaultRepositoryStatistics.FACET_ID)).andReturn(Arrays.asList(stats1.getName(), stats2.getName()));
    expect(metadataRepository.getMetadataFacet(session, TEST_REPO_ID, DefaultRepositoryStatistics.FACET_ID, stats2.getName())).andReturn(stats2);
