    expect(metadataRepository.getMetadataFacets(session, TEST_REPO_ID, DefaultRepositoryStatistics.FACET_ID)).andReturn(Collections.<String>emptyList());
    metadataRepositoryControl.replay();
    repositoryStatisticsManager.addStatisticsAfterScan(TEST_REPO_ID, startTime1, stats1.getScanEndTime(), 56345, 45);
    repositoryStatisticsManager.addStatisticsAfterScan(TEST_REPO_ID, startTime2, stats2.getScanEndTime(), 56345, 45);
    assertNotNull(repositoryStatisticsManager.getLastStatistics(TEST_REPO_ID));
    repositoryStatisticsManager.deleteStatistics(TEST_REPO_ID);
    assertNull(repositoryStatisticsManager.getLastStatistics(TEST_REPO_ID));
    metadataRepositoryControl.verify();
}

